using ChipDock.Core;
namespace ChipDock;

/// Managed buffers and native ABI declarations are generated by Interoptopus.
internal static class SerialBackend
{
    private static void Check(string? error) { if (error is not null) throw new InvalidOperationException(error); }
    // Finish queued calls before disconnecting so a pending connect cannot reopen the port.
    internal static void Shutdown() => Disconnect().GetAwaiter().GetResult();
    internal static Task<List<PortInfo>> Ports() => NativeWorker.Serial.Run(() =>
    {
        using var wire = Interop.chipdock_serial_ports().AsOk();
        var response = wire.Unwire(); Check(response.error); return response.payload;
    });
    internal static Task<PollBatch> Poll() => NativeWorker.Serial.Run(() =>
    {
        using var wire = Interop.chipdock_serial_poll().AsOk();
        var response = wire.Unwire(); Check(response.error); return response.payload ?? throw new InvalidOperationException("核心未返回串口状态");
    });
    internal static Task<SerialStatus> Connect(string path, SerialConfig config) => NativeWorker.Serial.Run(() =>
    {
        using var request = new SerialConnectRequest { path = path, config = config }.Wire();
        using var wire = Interop.chipdock_serial_connect(request).AsOk();
        var response = wire.Unwire(); Check(response.error);
        var status = response.payload ?? throw new InvalidOperationException("核心未返回连接状态");
        return status;
    });
    internal static Task<SerialStatus> Disconnect() => NativeWorker.Serial.Run(() =>
    {
        using var wire = Interop.chipdock_serial_disconnect().AsOk();
        var response = wire.Unwire(); Check(response.error);
        var status = response.payload ?? throw new InvalidOperationException("核心未返回连接状态");
        return status;
    });
    internal static Task Send(string text, SendFormat format, LineEnding lineEnding) => NativeWorker.Serial.Run(() =>
    {
        using var request = new SerialSendRequest { text = text, format = format, line_ending = lineEnding }.Wire();
        using var wire = Interop.chipdock_serial_send(request).AsOk(); Check(wire.Unwire().error);
    });
}
